<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<title>CAVE PILLOT // autonomous drone</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Chakra+Petch:wght@500;600;700&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#05120f; --teal:#2ec4b6; --teal2:#5ff2e2; --amber:#ffb454;
    --amber2:#ffd08a; --panel: rgba(7,22,18,.72); --line: rgba(95,242,226,.22);
    --display:'Chakra Petch',system-ui,sans-serif; --mono:'Space Mono',ui-monospace,monospace;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%;overflow:hidden;background:var(--ink);color:#dff7f2;
    font-family:var(--mono);-webkit-font-smoothing:antialiased;}
  #game{position:fixed;inset:0;display:block}

  .hud{position:fixed;inset:0;pointer-events:none;z-index:5}
  .hud::before{content:"";position:absolute;inset:0;
    background:
      linear-gradient(180deg,rgba(4,12,10,.55),transparent 22% 78%,rgba(4,12,10,.6)),
      radial-gradient(120% 120% at 50% 50%,transparent 62%,rgba(2,7,6,.6) 100%);
    mix-blend-mode:multiply}
  .hud::after{content:"";position:absolute;inset:0;opacity:.45;
    background:repeating-linear-gradient(0deg,rgba(255,255,255,.03) 0 1px,transparent 1px 3px)}

  .brand{position:fixed;top:20px;left:22px;display:flex;gap:12px;align-items:flex-start}
  .dotmark{font-size:16px;color:var(--teal2);line-height:1;margin-top:6px;text-shadow:0 0 12px var(--teal2)}
  .brand h1{font-family:var(--display);font-weight:700;font-size:clamp(17px,2.4vw,22px);
    letter-spacing:.24em;color:#ecfbf8}
  .brand h1 b{color:var(--amber2);font-weight:700}
  .brand .tag{font-size:10px;letter-spacing:.34em;color:var(--teal);margin-top:5px;opacity:.85}

  .rec{position:fixed;top:24px;right:24px;font-size:11px;letter-spacing:.34em;color:#ff8f7a;
    display:flex;align-items:center;gap:8px}
  .rec i{width:9px;height:9px;border-radius:50%;background:var(--amber);box-shadow:0 0 12px var(--amber);
    animation:rec 1.1s steps(1) infinite;font-style:normal}
  @keyframes rec{50%{opacity:.15}}

  .gauge{position:fixed;top:20px;right:22px;width:min(220px,32vw);z-index:5;font-size:11px}
  .g-row{display:flex;justify-content:space-between;letter-spacing:.2em;margin-bottom:5px}
  .g-row span{color:var(--teal)}
  .g-row b{color:#eafdf9;font-weight:700;font-variant-numeric:tabular-nums}
  .bar{height:5px;background:rgba(47,84,76,.55);border:1px solid var(--line);overflow:hidden;margin-bottom:12px}
  .fill{height:100%;width:0;background:linear-gradient(90deg,var(--teal),var(--amber2));
    box-shadow:0 0 12px rgba(255,180,84,.5);transition:width .12s linear}

  .telemetry{position:fixed;left:22px;bottom:20px;display:grid;gap:2px;
    font-size:11px;letter-spacing:.16em}
  .t{display:flex;align-items:baseline}
  .t span{width:66px;color:var(--teal);opacity:.8}
  .t b{color:#e8fbf7;font-weight:700;font-variant-numeric:tabular-nums}
  .t i{font-style:normal;width:26px;color:var(--amber);opacity:.75}

  .distance{position:fixed;right:24px;bottom:16px;text-align:right}
  .distance .label{font-size:10px;letter-spacing:.34em;color:var(--teal);opacity:.8}
  .distance .num{font-family:var(--display);font-weight:700;
    font-size:clamp(58px,11vw,124px);line-height:.82;color:#f4fffd;letter-spacing:.01em;
    font-variant-numeric:tabular-nums;text-shadow:0 0 34px rgba(95,242,226,.35)}
  .distance .unit{font-size:13px;letter-spacing:.3em;color:var(--amber2);margin-top:6px}

  .corner{position:fixed;width:26px;height:26px;border:2px solid var(--teal);opacity:.35}
  .c-tl{top:14px;left:14px;border-right:none;border-bottom:none}
  .c-tr{top:14px;right:14px;border-left:none;border-bottom:none}
  .c-bl{bottom:14px;left:14px;border-right:none;border-top:none}
  .c-br{bottom:14px;right:14px;border-left:none;border-top:none}

  .flash{position:fixed;inset:0;pointer-events:none;z-index:6;opacity:0;
    background:radial-gradient(circle at 30% 50%,rgba(255,150,70,.6),transparent 62%);
    box-shadow:inset 0 0 120px rgba(255,120,40,.5)}
  .flash.go{animation:flash .55s ease-out}
  @keyframes flash{0%{opacity:1}100%{opacity:0}}
</style>
</head>
<body>
<canvas id="game"></canvas>

<div class="hud">
  <div class="corner c-tl"></div><div class="corner c-tr"></div>
  <div class="corner c-bl"></div><div class="corner c-br"></div>

  <div class="brand">
    <div class="dotmark">◈</div>
    <div>
      <h1>CAVE <b>PILLOT</b></h1>
      <div class="tag">AUTONOMOUS DRONE · SECTOR 7</div>
    </div>
  </div>

  <div class="rec"><i></i>REC</div>

  <div class="gauge">
    <div class="g-row"><span>THRUST</span><b id="thrustV">0</b></div>
    <div class="bar"><div class="fill" id="thrustF"></div></div>
  </div>

  <div class="telemetry">
    <div class="t"><span>ALT</span><b id="alt">— — —</b></div>
    <div class="t"><span>VEL</span><b id="vel">000</b><i>m/s</i></div>
    <div class="t"><span>SCR</span><b id="scr">00</b></div>
  </div>

  <div class="distance">
    <div class="label">DISTANCE</div>
    <div class="num" id="dist">0000</div>
    <div class="unit">METRES</div>
  </div>
</div>
<div class="flash" id="flash"></div>

<script>
(function(){
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const distEl=$('dist'), altEl=$('alt'), velEl=$('vel'), scrEl=$('scr'),
        thrustF=$('thrustF'), thrustV=$('thrustV'), flashEl=$('flash');

  let W=0,H=0,DPR=1;
  function resize(){
    DPR = Math.min(window.devicePixelRatio||1, 2);
    W = window.innerWidth; H = window.innerHeight;
    canvas.width = W*DPR; canvas.height = H*DPR;
    canvas.style.width = W+'px'; canvas.style.height = H+'px';
    ctx.setTransform(DPR,0,0,DPR,0,0);
  }
  window.addEventListener('resize', resize); resize();

  // ---- tuning -------------------------------------------------------------
  const CFG = {baseSpeed:230, ramp:20, scrollBase:1.1, scrollGain:9, viewLead:150,
               size:11, wallH:8, trailLen:110, maxAccel:1500, baseAccel:20};

  const SHIPX = 0.30;

  // ---- state -------------------------------------------------------------
  let offset=0, distance=0, speed=CFG.baseSpeed, lastT=0;
  let nearWarn=0, shakeTime=0;
  const ship = {y:H/2, vy:0, tilt:0, v:0};

  // ---- field helpers -----------------------------------------------------
  const FREQ=0.0085, HALF=0.5;
  function cavex(wo){ // ground-to-ground thickness (periodic)
    return H*(0.34 + 0.15*Math.sin(wo*FREQ) + 0.06*Math.sin(wo*FREQ*2.7+1.3)
              + 0.04*Math.sin(wo*FREQ*4.6+2.1));
  }
  function midx(wo){
    return H*0.5 + (H*0.16)*Math.sin(wo*FREQ*0.55+1.7)
               + (H*0.08)*Math.sin(wo*FREQ*1.3+0.4);
  }
  function cavexAt(x){ return cavex(x+offset); }
  function midAt(x){ return midx(x+offset); }
  function cavity(cx){ const c=cavexAt(cx), m=midAt(cx);
    return {top:m-c/2, bot:m+c/2, c:c, m:m}; }

  // ---- particles ---------------------------------------------------------
  const dust=[], trail=[];
  for(let i=0;i<44;i++) dust.push({sx:Math.random()*W, sy:Math.random()*H,
    r:.6+Math.random()*1.6, sp:0.5+Math.random()*1.3, tw:Math.random()*7, a:.1+Math.random()*.4});
  const sparks=[];
  function spawnSparks(x,y,col,n){
    for(let i=0;i<n;i++){ const a=Math.random()*6.283, s=40+Math.random()*180;
      sparks.push({x,y, vx:Math.cos(a)*s, vy:Math.sin(a)*s, life:1, r:1+Math.random()*2.5, col}); }
  }

  // ---- update ------------------------------------------------------------
  function update(dt){
    speed = CFG.baseSpeed + offset*CFG.ramp;
    distance += speed*dt;
    offset   += (speed*CFG.scrollBase + speed*CFG.scrollGain)*dt;

    const cx = SHIPX*W + speed*CFG.viewLead*dt;  // look-ahead
    const c  = cavity(cx);
    const w  = CFG.wallH;
    const target = Math.max(c.top+w+CFG.size+6, Math.min(c.bot-w-CFG.size-6, c.m));
    const acc = (target-ship.y)*CFG.maxAccel;
    ship.vy += acc*dt;
    ship.vy -= ship.vy*3.0*dt;
    ship.y  += ship.vy*dt;

    ship.tilt += ((ship.vy*0.0016) - ship.tilt)*Math.min(1,dt*12);
    ship.v    += (Math.hypot(ship.vy, speed) - ship.v)*0.2;

    // nearness warning
    const floor = ship.y < c.top+w, ceil = ship.y > c.bot-w, sz=CFG.size;
    let near=1;
    if(!floor) near = Math.min(near, (ship.y-(c.top+w))/sz);
    if(!ceil)  near = Math.min(near, ((c.bot-w)-ship.y)/sz);
    nearWarn += (Math.min(1,Math.max(0,near))-nearWarn)*Math.min(1,dt*10);

    // ambient dust (only recycles once fully past the nose)
    for(const d of dust){
      d.sx -= speed*dt*0.55*d.sp; d.tw += dt*3;
      if(d.sx < -6){ d.sx = W + Math.random()*24; d.sy = Math.random()*H;
        d.sp = 0.5+Math.random()*1.3; d.a = .1+Math.random()*.4; }
    }

    // engine trail
    const tx = SHIPX*W + 12*Math.cos(ship.tilt);
    const ty = ship.y  + 12*Math.sin(ship.tilt);
    trail.push({x:tx,y:ty, life:1});
    if(trail.length>CFG.trailLen) trail.shift();
    for(const p of trail){ p.life-=dt*1.5; p.x-=speed*dt*0.15; }

    let dead=false;
    if(floor){ spawnSparks(SHIPX*W, c.top+w,'#ff7a3c',16); dead=true; }
    else if(ceil){ spawnSparks(SHIPX*W, c.bot-w,'#ff7a3c',16); dead=true; }
    if(dead){
      spawnSparks(SHIPX*W, ship.y,'#ffd08a',30);
      spawnSparks(SHIPX*W, ship.y,'#5ff2e2',24);
      ship.y = midx(cx*0.55)*0 + cavity(SHIPX*W).m; ship.vy=0; shakeTime=0.7;
      flashEl.classList.remove('go'); void flashEl.offsetWidth; flashEl.classList.add('go');
    }
    if(shakeTime>0) shakeTime-=dt;

    for(let i=sparks.length-1;i>=0;i--){ const s=sparks[i];
      s.x+=s.vx*dt; s.y+=s.vy*dt; s.vx*=0.93; s.vy*=0.93; s.life-=dt*2.2;
      if(s.life<=0) sparks.splice(i,1); }
  }

  // ---- drawing -----------------------------------------------------------
  function wallPathPts(topline){
    const step=12, pts=[];
    for(let i=-1;i<=W/step+1;i++){ const x=i*step, c=cavity(x);
      pts.push([x, topline?c.top:c.bot]); }
    return pts;
  }
  function strokeWall(pts, color, w, glow){
    ctx.lineJoin='round'; ctx.lineCap='round';
    for(let i=0;i<pts.length-1;i++){
      ctx.strokeStyle=color; ctx.lineWidth=w;
      ctx.shadowColor=glow; ctx.shadowBlur=8;
      ctx.beginPath(); ctx.moveTo(pts[i][0],pts[i][1]);
      ctx.lineTo(pts[i+1][0],pts[i+1][1]); ctx.stroke();
    }
    ctx.shadowBlur=0;
  }

  function background(){
    const g=ctx.createRadialGradient(W*0.32,H*0.5,10, W*0.5,H*0.5,Math.max(W,H)*0.75);
    g.addColorStop(0,'#0d2f2a'); g.addColorStop(0.55,'#08201d'); g.addColorStop(1,'#040f0d');
    ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
  }

  const N=7; // periodic lattice nodes
  function caveLayer(){
    const step=12;
    const top=wallPathPts(true), bot=wallPathPts(false);
    // exterior void
    ctx.fillStyle='#030c0a'; ctx.fillRect(-4,-4,W+8,H+8);
    // carved interior
    ctx.beginPath();
    ctx.moveTo(top[0][0],top[0][1]);
    for(let i=1;i<top.length;i++) ctx.lineTo(top[i][0],top[i][1]);
    for(let i=bot.length-1;i>=0;i--) ctx.lineTo(bot[i][0],bot[i][1]);
    ctx.closePath();
    const gr=ctx.createLinearGradient(0,0,0,H);
    gr.addColorStop(0,'#0d332d'); gr.addColorStop(0.5,'#0a241f'); gr.addColorStop(1,'#071a17');
    ctx.fillStyle=gr; ctx.fill();

    // interior ceiling / floor glow (light leaking in from the rim)
    ctx.save(); ctx.clip(); ctx.globalCompositeOperation='lighter';
    let gg=ctx.createLinearGradient(0,0,0,H*0.34);
    gg.addColorStop(0,'rgba(64,170,150,0.16)'); gg.addColorStop(1,'rgba(64,170,150,0)');
    ctx.fillStyle=gg; ctx.fillRect(0,0,W,H*0.34);
    gg=ctx.createLinearGradient(0,H,0,H*0.66);
    gg.addColorStop(0,'rgba(96,120,90,0.16)'); gg.addColorStop(1,'rgba(96,120,90,0)');
    ctx.fillStyle=gg; ctx.fillRect(0,H*0.66,W,H*0.34);
    ctx.restore();

    // rocks fixed to lattice nodes (discrete, each scrolls left & deletes)
    function rock(px,py,s,col,glow){
      ctx.shadowColor=glow; ctx.shadowBlur=14;
      ctx.strokeStyle=col; ctx.lineWidth=1.4; ctx.beginPath();
      for(let i=0;i<N;i++){ const a=i/N*6.283+px*0.02, rr=s*(0.6+0.45*Math.abs(Math.sin(a*2+px)));
        const x=px+Math.cos(a)*rr, y=py+Math.sin(a)*rr*0.8;
        i?ctx.lineTo(x,y):ctx.moveTo(x,y); }
      ctx.closePath(); ctx.stroke();
      ctx.shadowBlur=0; ctx.fillStyle='rgba(120,220,190,0.5)';
      ctx.beginPath(); ctx.arc(px,py,1.4,0,6.283); ctx.fill();
    }
    const gap = H*0.19;
    for(let base=Math.floor((offset-W*2)/gap)+1; base<=Math.ceil(offset/gap)+1; base++){
      const px = base*gap - offset; if(px<-40||px>W+40) continue;
      const c = cavity(px);
      rock(px, c.top+14, 6+4*Math.abs(Math.sin(base*1.7)), 'rgba(90,200,180,0.55)','#3fd6c0');
      rock(px, c.bot-14, 6+4*Math.abs(Math.cos(base*2.3)), 'rgba(130,140,100,0.5)','#9aa86a');
      if(((base%2)+2)%2===0)
        rock(px, c.m, 4+3*Math.abs(Math.sin(base)), 'rgba(255,190,110,0.45)','#ffb454');
    }
    strokeWall(top,'#5ff2e2',CFG.wallH,'rgba(95,242,226,0.9)');
    strokeWall(bot,'#ffb454',CFG.wallH,'rgba(255,180,84,0.9)');
  }

  function dustLayer(){
    for(const d of dust){
      const a = d.a*(0.5+0.5*Math.sin(d.tw));
      ctx.fillStyle='rgba(150,230,215,'+a.toFixed(3)+')';
      ctx.beginPath(); ctx.arc(d.sx,d.sy,d.r,0,6.283); ctx.fill();
    }
  }

  function trailLayer(){
    const TX=SHIPX*W, TY=ship.y;
    const g=ctx.createLinearGradient(TX,TY,TX-150,TY);
    g.addColorStop(0,'rgba(255,180,90,0.22)'); g.addColorStop(1,'rgba(255,120,60,0)');
    ctx.fillStyle=g; ctx.beginPath();
    ctx.moveTo(TX,TY-5);
    trail.forEach(p=>ctx.lineTo(p.x,p.y));
    ctx.lineTo(TX,TY+5); ctx.closePath(); ctx.fill();
    ctx.globalCompositeOperation='lighter';
    for(let i=0;i<trail.length;i++){ const p=trail[i];
      if(i%2||p.life<=0) continue;
      ctx.fillStyle='rgba(255,190,110,'+(p.life*0.5).toFixed(3)+')';
      ctx.beginPath(); ctx.arc(p.x,p.y,p.life*3,0,6.283); ctx.fill(); }
    ctx.globalCompositeOperation='source-over';
  }

  function sparksLayer(){
    ctx.globalCompositeOperation='lighter';
    for(const s of sparks){ ctx.globalAlpha=Math.max(0,s.life);
      ctx.fillStyle=s.col; ctx.beginPath(); ctx.arc(s.x,s.y,s.r*s.life+0.5,0,6.283); ctx.fill(); }
    ctx.globalAlpha=1; ctx.globalCompositeOperation='source-over';
  }

  function ambient(){
    ctx.globalCompositeOperation='lighter';
    const pulse=0.5+0.5*Math.sin(performance.now()*0.002);
    const rg=ctx.createRadialGradient(SHIPX*W,ship.y,4,SHIPX*W,ship.y,240);
    rg.addColorStop(0,'rgba(120,220,200,'+(0.10+0.06*pulse).toFixed(3)+')');
    rg.addColorStop(1,'rgba(120,220,200,0)');
    ctx.fillStyle=rg; ctx.fillRect(0,0,W,H);
    ctx.globalCompositeOperation='source-over';
    if(nearWarn>0.02){
      ctx.fillStyle='rgba(255,90,40,'+(0.10*nearWarn).toFixed(3)+')';
      ctx.fillRect(0,0,W,H*0.12); ctx.fillRect(0,H*0.88,W,H*0.12);
    }
  }

  function shipLayer(){
    const tx=SHIPX*W, ty=ship.y, s=CFG.size;
    ctx.save(); ctx.translate(tx,ty); ctx.rotate(ship.tilt);
    const eg=ctx.createRadialGradient(-s,0,1,-s,0,70);
    eg.addColorStop(0,'rgba(255,200,120,0.6)'); eg.addColorStop(1,'rgba(255,120,40,0)');
    ctx.fillStyle=eg; ctx.beginPath(); ctx.arc(-s,0,70,0,6.283); ctx.fill();

    const flick=0.6+Math.random()*0.4;
    const fg=ctx.createLinearGradient(-s-34*flick,0,-s+2,0);
    fg.addColorStop(0,'rgba(255,140,50,0)'); fg.addColorStop(0.6,'rgba(2
